import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"发布文档","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/publish-docs","contentType":"guide","prev":{"text":"维护项目文档","link":"/guides/documentation"},"next":false},"headers":[],"relativePath":"getting-started/publish-docs.md","filePath":"getting-started/publish-docs.md"}'),o={name:"getting-started/publish-docs.md"};function n(d,a,l,p,c,r){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="发布文档" tabindex="-1">发布文档 <a class="header-anchor" href="#发布文档" aria-label="Permalink to &quot;发布文档&quot;">​</a></h1><p>目标：将已验证的双语 Lab Word 文档发布到自己的 GitHub Pages。需要源码仓库的推送权限，首次 Pages 配置需要仓库管理权限。以下步骤会推送静态产物；本地构建本身不会发布。</p><h2 id="_1-核对仓库与构建" tabindex="-1">1. 核对仓库与构建 <a class="header-anchor" href="#_1-核对仓库与构建" aria-label="Permalink to &quot;1. 核对仓库与构建&quot;">​</a></h2><p>当前 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/site.json" target="_blank" rel="noreferrer">site.json</a>声明 <code>CaiZongyuan/labworld</code>，默认 base 为 <code>/labworld/</code>。先提交并推送源码，页脚链接才有对应线上版本。源码 Markdown 与 <code>apps/docs/public/</code> 是输入，<code>.generated</code> 和 VitePress dist 是派生产物。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>成功时构建检查报告双语页面与内部目标均在该 base 下解析。源码未发布时，本地页面仍可运行，但其 GitHub 版本链接不能证明线上可用性。</p><h2 id="_2-首次启用-pages" tabindex="-1">2. 首次启用 Pages <a class="header-anchor" href="#_2-首次启用-pages" aria-label="Permalink to &quot;2. 首次启用 Pages&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span></span></code></pre></div><p>脚本将 dist 提交到 <code>gh-pages</code>，不切换源码分支。到 GitHub <strong>Settings → Pages → Build and deployment</strong> 选择 <strong>Deploy from a branch</strong>、<code>gh-pages</code>、<code>/ (root)</code>。</p><p>GitHub CLI 登录后可执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request-build</span></span></code></pre></div><p>命令核对 Pages 配置、请求构建、匹配产物提交并读取线上源码版本。推送成功不等于站点可访问；构建未就绪时按脚本失败原因检查 Pages 状态。</p><h2 id="_3-后续发布" tabindex="-1">3. 后续发布 <a class="header-anchor" href="#_3-后续发布" aria-label="Permalink to &quot;3. 后续发布&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI</a>在 <code>main</code> 检查成功后推送验证过的文档产物并请求 Pages 构建；第一次仓库设置仍需完成。GitHub Actions token 推送不会自动触发 Pages 构建，因此脚本保留显式请求。</p><p>默认目标地址为 <code>https://caizongyuan.github.io/labworld/</code>；当前是否已上线需实际核对。自定义路径使用 <code>DOCS_BASE</code>，例如 <code>DOCS_BASE=/manual/ pnpm docs:build</code>。验证语言切换、搜索与章节导航后再发布。</p><hr><p>源码版本：<code>a10b900dc66b</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/getting-started/publish-docs.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,17)])])}const g=e(o,[["render",n]]);export{b as __pageData,g as default};
